<?php require 'config.php';require_role('volunteer');$s=db()->prepare("SELECT c.*,e.nama_kegiatan,e.tanggal,o.nama_organisasi FROM certificates c JOIN registrations r ON r.pendaftaran_id=c.pendaftaran_id JOIN events e ON e.kegiatan_id=r.kegiatan_id JOIN organizations o ON o.user_id=e.organisasi_id WHERE r.volunteer_id=? ORDER BY c.tanggal_terbit DESC");$s->execute([user()['user_id']]);$rows=$s->fetchAll();layout_start('Sertifikat');?><div class="page-heading"><span class="eyebrow">APRESIASI KONTRIBUSI</span><h1>Sertifikat saya</h1><p class="muted">Sertifikat kegiatan yang telah kamu ikuti.</p></div><div class="cards"><?php foreach($rows as $r):?><article class="certificate"><span class="eyebrow">VOLUNTEERHUB CERTIFICATE</span><h2>Sertifikat Partisipasi</h2><p>Diberikan kepada</p><h3><?=e(user()['nama'])?></h3><p>Atas partisipasi dalam kegiatan <b><?=e($r['nama_kegiatan'])?></b> yang diselenggarakan oleh <?=e($r['nama_organisasi'])?>.</p><small>No. <?=e($r['nomor_sertifikat'])?> · <?=date('d M Y',strtotime($r['tanggal_terbit']))?></small><button class="btn btn-outline small" onclick="window.print()">Cetak / Simpan PDF</button></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty"><h3>Belum ada sertifikat</h3><p>Sertifikat akan tersedia setelah kegiatan selesai dan kehadiranmu tercatat.</p></div><?php endif;?><?php layout_end(); ?>